108	    /**
109	     * The owner's salutation: the {@link #getTitle() title} followed by a space and the last name
110	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title has
111	     * been supplied.
112	     */
113	    public String getSalutation() {
114	        if (this.title == null || this.title.isEmpty()) {
115	            return this.getLastName();
116	        }
117	        return this.title + " " + this.getLastName();
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getAddressLine1() {
129	        return this.addressLine1;
130	    }
131	
132	    public void setAddressLine1(String addressLine1) {
133	        this.addressLine1 = addressLine1;
134	    }
135	
136	    public String getAddressLine2() {
137	        return this.addressLine2;
138	    }
139	
140	    public void setAddressLine2(String addressLine2) {
141	        this.addressLine2 = addressLine2;
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    /**
161	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
162	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
163	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
164	     * been set.
165	     */
166	    public String getTelephoneDisplay() {
167	        return Telephone.forDisplay(this.telephone);
168	    }
169	
170	    public String getEmail() {
171	        return this.email;
172	    }
173	
174	    public void setEmail(String email) {
175	        this.email = email;
176	    }
177	
178	    public String getPostcode() {
179	        return this.postcode;
180	    }
181	
182	    public void setPostcode(String postcode) {
183	        this.postcode = postcode;
184	    }
