218	    public Integer getNamesakeCount() {
219	        return this.namesakeCount;
220	    }
221	
222	    public void setNamesakeCount(Integer namesakeCount) {
223	        this.namesakeCount = namesakeCount;
224	    }
225	
226	    public Integer getHouseholdSize() {
227	        return this.householdSize;
228	    }
229	
230	    public void setHouseholdSize(Integer householdSize) {
231	        this.householdSize = householdSize;
232	    }
233	
234	    /**
235	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
236	     * the highest membership level held by the owner's household members when this owner was created.
237	     * {@code null} when the owner had no existing household member and so is uncapped.
238	     */
239	    public Integer getMembershipLevelCap() {
240	        return this.membershipLevelCap;
241	    }
242	
243	    public void setMembershipLevelCap(Integer membershipLevelCap) {
244	        this.membershipLevelCap = membershipLevelCap;
245	    }
246	
247	    /**
248	     * Whether this owner, though not a hard duplicate, matches an existing owner's last name by
249	     * Soundex and shares its postcode while holding a different identity key. Resolved at creation
250	     * and stored so it is reported consistently on every later read.
251	     */
252	    public Boolean getPossibleDuplicate() {
253	        return this.possibleDuplicate;
254	    }
255	
256	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
257	        this.possibleDuplicate = possibleDuplicate;
258	    }
259	
260	    /**
261	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
262	     * is not a possible duplicate.
263	     */
264	    public Integer getPossibleDuplicateOf() {
265	        return this.possibleDuplicateOf;
266	    }
267	
268	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
269	        this.possibleDuplicateOf = possibleDuplicateOf;
270	    }
271	
272	    /**
273	     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
274	     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
275	     * created owner is never deleted.
276	     */
277	    public boolean isDeleted() {
278	        return this.deleted;
279	    }
280	
281	    public void setDeleted(boolean deleted) {
282	        this.deleted = deleted;
283	    }
284	
285	    /**
286	     * The owner's identity key: the single derived value used to detect duplicate owners, formed as
287	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}
288	     * where an absent telephone or email contributes an empty string. Because the telephone is part
289	     * of the key, housemates that share a last name and postcode but hold different telephones have
290	     * distinct identity keys and are both allowed (and merely flagged as possible duplicates).
291	     */
292	    public String getIdentityKey() {
293	        String key = orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + Soundex.of(this.getLastName());
294	        return Sha256.hex(key);
295	    }
296	
297	    private static String orEmpty(String value) {
298	        return value == null ? "" : value;
299	    }
300	
301	    /**
302	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
303	     * last two digits of the {@link #getFiscalYear() fiscal year} of the business-day-adjusted
304	     * registration date (e.g. {@code 'SMI-0007-M27'}). Derived from the owner's own fields;
305	     * absent until both the customer code and registration date have been assigned.
306	     */
307	    public String getMembershipNumber() {
308	        if (this.customerCode == null || this.registrationDate == null) {
309	            return null;
310	        }
311	        return String.format("%s-M%02d", this.customerCode, FiscalYear.endingYear(this.registrationDate) % 100);
312	    }
313	
314	    /**
315	     * The owner's fiscal year, formatted {@code 'FY<YY>'} and derived from the business-day-adjusted
316	     * {@link #getRegistrationDate() registration date}. The fiscal year starts on 1 July; see
317	     * {@link FiscalYear}. Absent until a registration date has been assigned.
318	     */
319	    public String getFiscalYear() {
320	        if (this.registrationDate == null) {
321	            return null;
322	        }
323	        return FiscalYear.label(this.registrationDate);
324	    }
325	
326	    /**
327	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
328	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
329	     */
330	    public Integer getCheckDigit() {
331	        if (this.customerCode == null) {
332	            return null;
333	        }
334	        return Luhn.checkDigit(this.customerCode);
335	    }
336	
337	    /**
338	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July boundaries crossed
339	     * from the {@link #getRegistrationDate() registration date} up to today (see {@link FiscalYear}).
340	     * An owner still in their registration fiscal year has a tenure of zero. Absent until a
341	     * registration date is present.
342	     */
343	    public Long getTenureFiscalYears() {
344	        if (this.registrationDate == null) {
345	            return null;
346	        }
347	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
348	    }
349	
350	    /**
351	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
352	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
353	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
354	     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
355	     * year (the registration and current dates fall in different fiscal years).
356	     */
357	    public Integer getMembershipPoints() {
358	        int points = 0;
359	        boolean hasEmail = this.email != null && !this.email.isEmpty();
360	        if (hasEmail) {
361	            points += 2;
362	        }
363	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
364	        if (unique) {
365	            points += 1;
366	        }
367	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
368	        if (sharedHousehold) {
369	            points += 2;
370	        }
371	        Long tenureFiscalYears = getTenureFiscalYears();
372	        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
373	        if (tenured) {
374	            points += 3;
375	        }
376	        return points;
377	    }
378	
379	    /**
380	     * The owner's membership level, a number from 1 to 4 derived from the owner's
381	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
382	     * 4 for 6 or more. The level is then held to its {@link #getMembershipLevelCap() cap} (one above
383	     * the highest level among the owner's household members at creation), so a new owner cannot rank
384	     * more than one level above their household. An uncapped owner keeps the derived level.
385	     */
386	    public Integer getMembershipLevel() {
387	        int level = derivedMembershipLevel();
388	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
389	            return this.membershipLevelCap;
390	        }
391	        return level;
392	    }
393	
394	    private int derivedMembershipLevel() {
395	        int points = getMembershipPoints();
396	        if (points >= 6) {
397	            return 4;
398	        }
399	        if (points >= 4) {
400	            return 3;
401	        }
402	        if (points >= 2) {
403	            return 2;
404	        }
405	        return 1;
406	    }
407	
408	    /**
409	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
410	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
411	     * before a customer code has been assigned.
412	     */
413	    public String getLocality() {
414	        if (this.customerCode == null) {
415	            return Regions.UNKNOWN;
416	        }
417	        int separator = this.customerCode.indexOf('-');
418	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
419	    }
420	
421	    /**
422	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
423	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
424	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
425	     */
426	    public String getTimezone() {
427	        return Regions.timezoneOf(getLocality());
428	    }
429	
430	    /**
431	     * The owner's preferred contact channel, derived from the owner's own fields:
432	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
433	     */
434	    public String getContactPreference() {
435	        boolean hasEmail = this.email != null && !this.email.isEmpty();
436	        return hasEmail ? "EMAIL" : "PHONE";
437	    }
438	
439	    /**
440	     * The owner's age band, derived from the owner's own fields: the whole years between
441	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
442	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
443	     * (65 or older). Absent until a birth date and a registration date are both present.
444	     */
445	    public String getAgeBand() {
446	        if (this.birthDate == null || this.registrationDate == null) {
447	            return null;
448	        }
449	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
450	        if (age < 18) {
451	            return "MINOR";
452	        }
453	        return age < 65 ? "ADULT" : "SENIOR";
454	    }
455	
456	    /**
457	     * Resolve the effective registration date before persisting: default it to the server's
458	     * current date when none was supplied, then roll it forward off weekends so a newly
459	     * registered owner always has a business-day registration date. Every value derived from it
460	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
461	     * date.
462	     */
463	    @PrePersist
464	    private void resolveRegistrationDate() {
465	        if (this.registrationDate == null) {
466	            this.registrationDate = LocalDate.now();
467	        }
468	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
469	    }
470	
471	    /**
472	     * The owner's self link: the canonical API path of this owner, formatted
473	     * {@code "/api/owners/<id>"}. Absent until the owner has been assigned an id.
474	     */
475	    public String getSelfLink() {
476	        if (this.getId() == null) {
477	            return null;
478	        }
479	        return "/api/owners/" + this.getId();
480	    }
481	
482	    protected Set<Pet> getPetsInternal() {
483	        if (this.pets == null) {
484	            this.pets = new HashSet<>();
485	        }
486	        return this.pets;
487	    }
488	
489	    protected void setPetsInternal(Set<Pet> pets) {
490	        this.pets = pets;
491	    }
492	
493	    public List<Pet> getPets() {
494	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
495	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
496	        return Collections.unmodifiableList(sortedPets);
497	    }
498	
499	    public void setPets(List<Pet> pets) {
500	        this.pets = new HashSet<>(pets);
501	    }
502	
503	    public void addPet(Pet pet) {
504	        getPetsInternal().add(pet);
505	        pet.setOwner(this);
506	    }
507	
508	    /**
509	     * Return the Pet with the given name, or null if none found for this Owner.
510	     *
511	     * @param name to test
512	     * @return true if pet name is already in use
513	     */
514	    public Pet getPet(String name) {
515	        return getPet(name, false);
516	    }
517	
518	    /**
519	     * Return the Pet with the given name, or null if none found for this Owner.
520	     *
521	     * @param name to test
522	     * @return true if pet name is already in use
523	     */
524	    public Pet getPet(String name, boolean ignoreNew) {
525	        name = name.toLowerCase();
526	        for (Pet pet : getPetsInternal()) {
527	            if (!ignoreNew || !pet.isNew()) {
528	                String compName = pet.getName();
529	                compName = compName.toLowerCase();
530	                if (compName.equals(name)) {
531	                    return pet;
532	                }
533	            }
534	        }
535	        return null;
536	    }
537	
538	    public Pet getPet(Integer petId) {
539	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
540	    }
541	
542	    @Override
543	    public String toString() {
544	        return new ToStringCreator(this)
545	
546	            .append("id", this.getId())
547	            .append("new", this.isNew())
548	            .append("lastName", this.getLastName())
549	            .append("firstName", this.getFirstName())
550	            .append("address", this.address)
551	            .append("city", this.city)
552	            .append("telephone", this.telephone)
553	            .append("email", this.email)
554	            .toString();
555	    }
556	}
