150	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
151	        this.dailyOwnerLimitValidator = dailyOwnerLimitValidator;
152	        this.registrationDateValidator = registrationDateValidator;
153	        this.telephoneNormalizer = telephoneNormalizer;
