201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
204	        if (StringUtils.hasText(idempotencyKey)) {
205	            Optional<Owner> alreadyCreated = this.idempotencyStore.find(idempotencyKey)
206	                .map(this.clinicService::findOwnerById);
207	            if (alreadyCreated.isPresent()) {
208	                return new ResponseEntity<>(toOwnerDto(alreadyCreated.get()), HttpStatus.OK);
209	            }
210	        }
211	        Owner owner = createOwner(ownerFieldsDto);
212	        if (StringUtils.hasText(idempotencyKey)) {
213	            this.idempotencyStore.remember(idempotencyKey, owner.getId());
214	        }
215	        HttpHeaders headers = new HttpHeaders();
216	        headers.setLocation(UriComponentsBuilder.newInstance()
217	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
218	        return new ResponseEntity<>(toOwnerDto(owner), headers, HttpStatus.CREATED);
219	    }
220	
221	    /**
222	     * Apply every create-time rule to the submitted fields and persist the resulting owner.
223	     */
224	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
225	        this.addressFormNormalizer.normalize(ownerFieldsDto);
226	        this.ownerRequestValidator.validate(ownerFieldsDto);
227	        this.postcodeValidator.validate(ownerFieldsDto);
228	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
229	        this.registrationDateValidator.validate(ownerFieldsDto.getRegistrationDate());
230	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
231	        ownerFieldsDto.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
232	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
233	        this.disposableEmailDomainValidator.validate(ownerFieldsDto.getEmail());
234	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
235	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
236	        // The householdId is deterministic from (lastName, postcode), so every owner carries the
237	        // identifier of its household automatically.
238	        owner.setHouseholdId(
239	            this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
240	        if (sharesHousehold) {
241	            // A declared household member is deliberately allowed and, being declared, is never a
242	            // suspected duplicate.
243	            owner.setPossibleDuplicate(false);
244	            owner.setPossibleDuplicateOf(null);
245	        } else {
246	            this.duplicateOwnerValidator.validate(owner);
247	            Integer possibleDuplicateOf = this.possibleDuplicateDetector.findPossibleDuplicate(owner);
248	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
249	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
250	        }
251	        owner.setCustomerCode(
252	            this.customerCodeGenerator.generate(owner.getPostcode(), owner.getTelephone(),
253	                owner.getLastName()));
254	        owner.setNamesakeCount(
255	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
256	        owner.setHouseholdSize(this.householdSizeCalculator.size(owner));
257	        owner.setMembershipLevelCap(this.membershipLevelCapCalculator.cap(owner));
258	        this.clinicService.saveOwner(owner);
259	        this.ownerAuditLogger.created(owner);
260	        return owner;
261	    }
